export const languages = [
  { code: 'en', label: 'English' },
  { code: 'es', label: 'Español' },
  { code: 'fr', label: 'Français' },
  { code: 'pt-BR', label: 'Português (Brasil)' },
  { code: 'it', label: 'Italiano' },
  { code: 'ja', label: '日本語' },
  { code: 'zh-CN', label: '简体中文' },
  { code: 'ko', label: '한국어' },
  { code: 'nl', label: 'Nederlands' },
  { code: 'de', label: 'Deutsch' },
] as const

export type Language = typeof languages[number]['code']

export function isLanguage(value: string): value is Language {
  return languages.some(({ code }) => code === value)
}

export function browserLanguage(preferences: readonly string[]): Language {
  for (const preference of preferences) {
    const exact = languages.find(({ code }) => code.toLowerCase() === preference.toLowerCase())
    if (exact) return exact.code
    const base = preference.toLowerCase().split('-')[0]
    const match = languages.find(({ code }) => code.toLowerCase().split('-')[0] === base)
    if (match) return match.code
  }
  return 'en'
}

export function format(text: string, values: Record<string, string | number>): string {
  return text.replace(/\{(\w+)\}/gu, (_, key: string) => String(values[key] ?? `{${key}}`))
}

